// notice an algorithm change.

// runeRange is an inclusive, ascending, non-overlapping code point interval.
type runeRange struct {
	lo, hi rune
}

// inRanges reports whether r falls in one of the ranges, which must be sorted ascending.
func inRanges(ranges []runeRange, r rune) bool {
	lo, hi := 0, len(ranges)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		switch {
		case r < ranges[mid].lo:
			hi = mid - 1
		case r > ranges[mid].hi:
			lo = mid + 1
		default:
			return true
		}
	}
	return false
}

// inRunes reports whether r is present in a set sorted ascending.
func inRunes(runes []rune, r rune) bool {
	lo, hi := 0, len(runes)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		switch {
		case r < runes[mid]:
			hi = mid - 1
		case r > runes[mid]:
			lo = mid + 1
		default:
			return true
		}
	}
	return false
}

